//! Cargo-driven `oleacc.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is oleacc-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6f890000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fea8000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fea8000000u64)),
        o => panic!("oleacc-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/oleacc/oleacc_classes_t.o", "dll/win32/oleacc/oleacc_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:pseh", "engine:oldnames", "import:oleaut32", "import:ole32", "import:user32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk"],
        "x86_64" => &["dll/win32/oleacc/oleacc_classes_t.o", "dll/win32/oleacc/oleacc_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:pseh", "engine:oldnames", "import:oleaut32", "import:ole32", "import:user32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll"],
        "aarch64" => &["dll/win32/oleacc/oleacc_classes_t.o", "dll/win32/oleacc/oleacc_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:pseh", "engine:oldnames", "import:oleaut32", "import:ole32", "import:user32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/oleacc",
        "dll/win32/oleacc",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/symcrypt/inc",
        "vendor/symcrypt/lib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "ENTRY_PREFIX=OLEACC_",
        "PROXY_DELEGATION",
        "WINE_REGISTER_DLL",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .rust_staticlib("oleacc-rust")
        .c_from_compile_db("oleacc_shims", &["dll/win32/oleacc/rust_cohab_stub.c", "dll/win32/oleacc/oleacc_classes_p.c", "dll/win32/oleacc/proxy.dlldata.c"])
        .rc("dll/win32/oleacc/oleacc.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/oleacc/oleacc.spec", "oleacc.dll")
        .spec_stubs()
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
